const pb = global.get("pb");
const entries = msg.payload;

if (entries.length > 0) {
    const newest = entries.reduce((a, b) => a.timeCreated > b.timeCreated ? a : b);
    const connId = newest.connection_id || (msg.connection && msg.connection.id);
    const client = newest.client;

    if (connId && client) {
        pb.setTimestamp(connId, client, newest.timeCreated);
    }
}

return msg;
